window.AUTH=window.AUTH||{};window.AUTH["17-9560"]={"d":"17-9560","id":"2018/17-9560","n":"Rehaif v. United States","briefs":[{"k":"petitioner","label":"Brief of petitioner Hamid Rehaif","date":"2019-02-22","url":"https://www.supremecourt.gov/DocketPDF/17/17-9560/89331/20190222155834806_17-9560ts.pdf","side":"pet","n":44},{"k":"respondent","label":"Brief of respondent United States","date":"2019-03-25","url":"https://www.supremecourt.gov/DocketPDF/17/17-9560/93150/20190325190401864_17-9560bsUnitedStates.pdf","side":"res","n":140},{"k":"reply","label":"Reply of petitioner Hamid Rehaif","date":"2019-04-12","url":"https://www.supremecourt.gov/DocketPDF/17/17-9560/96293/20190412135543165_17-9560rb.pdf","side":"pet","n":41}],"opinion":"https://www.supremecourt.gov/opinions/18pdf/17-9560_new_onkq.pdf","tr":true,"items":[{"t":"case","label":"Ali v. Fed. Bureau of Prisons","cite":"552 U.S. 214","y":2008,"id":"2007/06-9130","sc":1,"sum":"The Court agreed with the 11th Circuit and, in a 5-4 majority opinion written by Justice Clarence Thomas, held that the use of the word \"any\" should be given its normal interpretation, encompassing all federal officers whether or not they were involved in enforcing customs or excise laws.","sumSrc":"Oyez","by":{"0":"12"}},{"t":"case","label":"Almendarez–Torres v. United States","cite":"523 U.S. 224","y":1998,"id":"1997/96-6839","sc":1,"sum":"The Court held that subsection (b)(2) of 8 USC section 1326(a) is a penalty provision, which authorizes a court to increase the sentence for a recidivist, and does not define a separate crime. \"[W]e note that the relevant statutory subject matter is recidivism,\" wrote Justice Breyer, \"[t]hat subject matter -- prior commission of a serious crime -- is as typical a sentencing factor as one might imagine.\" Therefore, neither subsection (b)(2) nor the due process clause of the Fifth Amendment required that the government charge a prior aggravated felony conviction in the alien's indictment for the imposition of a sentence more than 2 years.","sumSrc":"Oyez","by":{"0":"20"}},{"t":"case","label":"Am. Tobacco Co. v. Patterson","cite":"456 U.S. 63","y":1982,"id":"1981/80-1199","sc":1,"sum":"The Court held that the absence of any sort of grandfather clause or explicit distinction between pre- and post-Act systems meant that the section applied to all seniority systems, regardless of when they were put in place. There was no clear legislative history to support the distinction between pre-existing systems and those that were implemented later.","sumSrc":"Oyez","by":{"0":"12"}},{"t":"case","label":"Cannon v. Univ. of Chi.","cite":"441 U.S. 677","y":1979,"id":"1978/77-926","sc":1,"sum":"Petitioner may maintain her lawsuit, despite the absence of any express authorization for it in Title IX.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"22, 23"}},{"t":"case","label":"Cent. Bank of Denver v. First Interstate Bank","cite":"511 U.S. 164","y":1994,"id":"1993/92-854","sc":1,"op":6,"sum":"The Court held that the Securities Exchange Act only prohibits manipulative or deceitful actions, and it can only be used to prosecute such actions. Since the charge of aiding and abetting is not directly covered in the statute, companies cannot be liable for such actions.","sumSrc":"Oyez","by":{"0":"24","2":"19"}},{"t":"case","label":"Conn. Nat’l Bank v. Germain","cite":"503 U.S. 249","y":1992,"id":"1991/90-1791","sc":1,"sum":"An interlocutory order issued by a district court sitting as a court of appeals in bankruptcy is appealable under the unambiguous language of 28 U. S. C. § 1292. That section provides for review in the courts of appeals, in certain circumstances, of \"[i]nterlocutory orders of the district courts,\" and does not limit such review to orders issued by district courts sitting as bankruptcy trial courts rather than …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"12"}},{"t":"case","label":"Culbertson v. Berryhill","cite":"139 S. Ct. 517","y":2019,"id":"2018/17-773","sc":1,"sum":"The Social Security Act’s fee cap of 25% of past-due benefits imposed on attorneys who successfully represent Title II benefit claimants in court proceedings applies only to fees for court representation and not to aggregate fees for both court and agency representation.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"12, 13"}},{"t":"case","label":"Dennis v. United States","cite":"341 U.S. 494","y":1951,"id":"1940-1955/341us494","sc":1,"sum":"The Court decided that the Smith Act, a federal law which made it a crime to advocate or organize for the purpose of overthrowing the government, did not violate the First Amendment of the Constitution.","sumSrc":"Oyez","by":{"0":"24"}},{"t":"case","label":"Elonis v. United States","cite":"135 S. Ct. 2001","y":2015,"id":"2014/13-983","sc":1,"op":1,"sum":"The Court found that in order to violate the transmission of threats provision, the threat requires both an objective and subjective intent.","sumSrc":"Oyez","by":{"0":"17, 18","1":"26, 42"}},{"t":"case","label":"Flores-Figueroa v. United States","cite":"556 U.S. 646","y":2009,"id":"2008/08-108","sc":1,"op":3,"sum":"The Court found that in order to prove aggravated identity theft, the government needs to prove that the defendant knew that the identification he possessed belonged to another person.","sumSrc":"Oyez","by":{"0":"passim","1":"41","2":"3"}},{"t":"case","label":"Jennings v. Rodriguez","cite":"138 S. Ct. 830","y":2018,"id":"2017/15-1204","sc":1,"sum":"The Court held that non-citizens who are subject to mandatory detention under the Immigration and Nationality Act are not entitled to periodic bond hearings. with the possibility of release if they are detained for longer than six months.","sumSrc":"Oyez","by":{"0":"25"}},{"t":"case","label":"Liparota v. United States","cite":"471 U.S. 419","y":1985,"id":"1984/84-5108","sc":1,"op":3,"sum":"Absent any indication of a contrary purpose in the statute's language or legislative history, the Government in a prosecution for violation of § 2024(b)(1) must prove that the defendant knew that his acquisition or possession of food stamps was in a manner unauthorized by statute or regulations.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"passim","1":"41","2":"1, 12"}},{"t":"case","label":"Morissette v. United States","cite":"342 U.S. 246","y":1952,"id":"scdb/1951-028","sc":1,"op":5,"ar":3,"sum":"1. A criminal intent is an essential element of an offense under 18 U. S. C. § 641, which provides that \"whoever embezzles, steals, purloins, or knowingly converts\" property -of the United States is punishable by fine and imprisonment.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"9, 18, 27","1":"15"}},{"t":"case","label":"Pa. Dep’t Pub. Welfare v. Davenport","cite":"495 U.S. 552","y":1990,"id":"1989/89-156","sc":1,"sum":"The Code's language and structure demonstrate that restitution obligations constitute \"debts\" within the meaning of § 101(11) and are therefore dischargeable under Chapter 13.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"22"}},{"t":"case","label":"Rodriguez v. United States","cite":"480 U.S. 522","y":1987,"id":"1986/86-5504","sc":1,"sum":"Section 3147 does not divest sentencing judges of their § 3651 authority. Nothing in the language of the two provisions suggests the existence of an \"irreconcilable conflict\" from which an intent to work an implicit partial repeal of § 3651 may be inferred; to the contrary, the provisions fit together quite sensibly. Moreover, the totality of the legislative history of the Act of which §3147 is a part demonstrates …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"34","2":"19"}},{"t":"case","label":"Staples v. United States","cite":"511 U.S. 600","y":1994,"id":"1993/92-1441","sc":1,"op":8,"ar":1,"sum":"To obtain a § 5861(d) conviction, the Government should have been required to prove beyond a reasonable doubt that Staples knew that his rifle had the characteristics that brought it within the statutory definition of a machinegun.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"12, 17, 26","1":"21, 43, 44, 45","2":"9, 10, 19, 20, 21"}},{"t":"case","label":"Torres v. Lynch","cite":"136 S. Ct. 1619","y":2016,"url":"https://www.courtlistener.com/c/S.%20Ct./136/1619/","sc":1,"op":2,"by":{"0":"31","1":"21","2":"3"}},{"t":"case","label":"United States v. Feola","cite":"420 U.S. 671","y":1975,"id":"1974/73-1123","sc":1,"op":5,"sum":"The Court held that, given the legislative history of the statute, Congress clearly intended it to afford “maximum protection” to federal officers. This purpose was best satisfied with a looser understanding of intent. The Court held that this ruling was not unfair to the defendant because it did not make a previously legal action illegal. Intent to assault is criminal, regardless of the intended victim.","sumSrc":"Oyez","by":{"0":"31, 32","2":"4"}},{"t":"case","label":"United States v. Games-Perez","cite":"667 F.3d 1136","y":2012,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/667/1136/","op":4,"by":{"0":"13, 14, 17, 18","1":"32","2":"passim"}},{"t":"case","label":"United States v. Games-Perez","cite":"695 F.3d 1104","y":2012,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/695/1104/","by":{"0":"14, 23, 25, 26","2":"16"}},{"t":"case","label":"United States v. Int’l Minerals & Chem. Corp.","cite":"402 U.S. 558","y":1971,"id":"1970/557","sc":1,"sum":"Appellee was charged by information with shipping sulfuric and hydrofluosilicic acids in interstate commerce and that it \"did knowingly fail to show on the shipping papers the required classification of said property, to wit, Corrosive Liquid, in violation of 49 C. F. R. 173.437,\" issued pursuant to 18 U. S. C. § 834 (a). Section 834 (f) provides that whoever \"knowingly violates any such regulation\" shall be fined …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"20","1":"23"}},{"t":"case","label":"United States v. Kozminski","cite":"487 U.S. 931","y":1988,"id":"1987/86-2000","sc":1,"sum":"The Court held that precedent had established that the type of involuntary servitude prohibited by the Thirteenth Amendment is limited to that “enforced by the use or threatened use of physical or legal coercion.” Involuntary servitude had never before been extended to cover labor compelled by the use of psychological coercion.","sumSrc":"Oyez","by":{"0":"30"}},{"t":"case","label":"United States v. Langley","cite":"62 F.3d 602","y":1995,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/62/602/","op":1,"by":{"0":"22, 23, 24","1":"32"}},{"t":"case","label":"United States v. Pruner","cite":"606 F.2d 871","y":1979,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/606/871/","op":2,"by":{"0":"21","1":"30"}},{"t":"case","label":"United States v. Renner","cite":"496 F.2d 922","y":1974,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/496/922/","op":2,"by":{"0":"25","1":"31"}},{"t":"case","label":"United States v. Ruisi","cite":"460 F.2d 153","y":1972,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/460/153/","by":{"0":"21"}},{"t":"case","label":"United States v. Turkette","cite":"452 U.S. 576","y":1981,"id":"1980/80-808","sc":1,"sum":"The term \"enterprise\" as used in RICO encompasses both legitimate and illegitimate enterprises.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"20"}},{"t":"case","label":"United States v. U.S. Gypsum Co.","cite":"438 U.S. 422","y":1978,"id":"1977/76-1560","sc":1,"op":1,"sum":"Several major gypsum board manufacturers and various of their officials were indicted for violations of § 1 of the Sherman Act by allegedly engaging in a price-fixing conspiracy. One of the types of actions allegedly taken in formulating and effectuating the conspiracy was interseller price verification, i. e., the practice of telephoning a competing manufacturer to determine the price being currently offered on …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"24","1":"44","2":"21"}},{"t":"case","label":"United States v. Ware","cite":"758 F.2d 557","y":1985,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.2d/758/557/","by":{"0":"21"}},{"t":"case","label":"United States v. X-Citement Video, Inc.","cite":"513 U.S. 64","y":1994,"id":"1994/93-723","sc":1,"op":7,"ar":1,"sum":"The Court relied on an awkward grammatical construction as it held that the term \"knowingly\" applied to the entire passage of the law. Writing for the majority, Chief Justice William Rehnquist stated that other interpretations failed to make sense since Congress obviously did not envision people accidentally mailing underage pornographic materials.","sumSrc":"Oyez","by":{"0":"passim","1":"41","2":"9"}},{"t":"case","label":"Washington v. Glucksberg","cite":"521 U.S. 702","y":1997,"id":"1996/96-110","sc":1,"sum":"The Court decided that a law banning physician-assisted suicide does not violate the Due Process Clause of the Fourteenth Amendment.","sumSrc":"Oyez","by":{"0":"27, 28"}},{"t":"case","label":"Wirtz v. Local 153, Bottle Blowers Ass’n","cite":"389 U.S. 463","y":1968,"id":"1967/57","sc":1,"sum":"When the Secretary of Labor proves the existence of a § 401 violation that may have affected the outcome of a challenged election, he is not deprived of the right to a court order voiding the challenged election and directing that a new election be conducted under his supervision because the union has meanwhile conducted another unsupervised election. Pp. 467-476. 372 F. 2d 86, reversed and remanded.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"19, 20"}},{"t":"case","label":"Yates v. United States","cite":"135 S. Ct. 1074","y":2015,"id":"2014/13-7451","sc":1,"sum":"The Court ruled that a “tangible item” as defined by Section 1519 of the Sarbanes-Oxley Act is one used to record or preserve information.","sumSrc":"Oyez","by":{"0":"28","2":"21"}},{"t":"const","label":"Amendment V","clauses":[["grand-jury","Grand Jury Clause"],["double-jeopardy","Double Jeopardy Clause"],["self-incrimination","Self-Incrimination Clause"],["due-process-5","Due Process Clause (Fifth Amendment)"],["takings","Takings Clause"]],"text":"No person shall be held to answer for a capital, or otherwise infamous crime, unless on a presentment or indictment of a Grand Jury, except in cases arising in the land or naval forces, or in the Militia, when in actual service in time of War or public danger; nor shall any person be subject for the same offence to be twice put in jeopardy of life or limb; nor shall be compelled in any criminal case to be a witness against himself, nor be deprived of life, liberty, or property, without due process of law; nor shall private property be taken for public use, without just compensation.","by":{"0":"1"}},{"t":"usc","label":"18 U.S.C. § 922","url":"https://www.law.cornell.edu/uscode/text/18/922","subs":["(g)","(d)","(d)(5)(A)","(g)(1)","(g)(2)","(g)(3)","(g)(4)","(g)(5)","(g)(5)(A)","(g)(7)","(g)(8)(A)","(g)(9)","(h)","(i)"],"stext":{"head":"§922. Unlawful acts","paras":[[0,"(a) It shall be unlawful—"],[1,"(1) for any person—"],[2,"(A) except a licensed importer, licensed manufacturer, or licensed dealer, to engage in the business of importing, manufacturing, or dealing in firearms, or in the course of such business to ship, transport, or receive any firearm in interstate or foreign commerce; or"],[2,"(B) except a licensed importer or licensed manufacturer, to engage in the business of importing or manufacturing ammunition, or in the course of such business, to ship, transport, or receive any ammunition in interstate or foreign commerce;"],[1,"(2) for any importer, manufacturer, dealer, or collector licensed under the provisions of this chapter to ship or transport in interstate or foreign commerce any firearm to any person other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, except that—"],[2,"(A) this paragraph and subsection (b)(3) shall not be held to preclude a licensed importer, licensed manufacturer, licensed dealer, or licensed collector from returning a firearm or replacement firearm of the same kind and type to a person from whom it was received; and this paragraph shall not be held to preclude an individual from mailing a firearm owned in compliance with Federal, State, and local law to a licensed importer, licensed manufacturer, licensed dealer, or licensed collector;"],[2,"(B) this paragraph shall not be held to preclude a licensed importer, licensed manufacturer, or licensed dealer from depositing a firearm for conveyance in the mails to any officer, employee, agent, or watchman who, pursuant to the provisions of section 1715 of this title, is eligible to receive through the mails pistols, revolvers, and other firearms capable of being concealed on the person, for use in connection with his official duty; and"],[2,"(C) nothing in this paragraph shall be construed as applying in any manner in the District of Columbia, the Commonwealth of Puerto Rico, or any possession of the United States differently than it would apply if the District of Columbia, the Commonwealth of Puerto Rico, or the possession were in fact a State of the United States;"],[1,"(3) for any person, other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector to transport into or receive in the State where he resides (or if the person is a corporation or other business entity, the State where it maintains a place of business) any firearm purchased or otherwise obtained by such person outside that State, except that this paragraph (A) shall not preclude any person who lawfully acquires a firearm by bequest or intestate succession in a State other than his State of residence from transporting the firearm into or receiving it in that State, if it is lawful for such person to purchase or possess such firearm in that State, (B) shall not apply to the transportation or receipt of a firearm obtained in conformity with subsection (b)(3) of this section, and (C) shall not apply to the transportation of any firearm acquired in any State prior to the effective date of this chapter;"],[1,"(4) for any person, other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, to transport in interstate or foreign commerce any destructive device, machinegun (as defined in section 5845 of the Internal Revenue Code of 1986), short-barreled shotgun, or short-barreled rifle, except as specifically authorized by the Attorney General consistent with public safety and necessity;"],[1,"(5) for any person (other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector) to transfer, sell, trade, give, transport, or deliver any firearm to any person (other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector) who the transferor knows or has reasonable cause to believe does not reside in (or if the person is a corporation or other business entity, does not maintain a place of business in) the State in which the transferor resides; except that this paragraph shall not apply to (A) the transfer, transportation, or delivery of a firearm made to carry out a bequest of a firearm to, or an acquisition by intestate succession of a firearm by, a person who is permitted to acquire or possess a firearm under the laws of the State of his residence, and (B) the loan or rental of a firearm to any person for temporary use for lawful sporting purposes;"],[1,"(6) for any person in connection with the acquisition or attempted acquisition of any firearm or ammunition from a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, knowingly to make any false or fictitious oral or written statement or to furnish or exhibit any false, fictitious, or misrepresented identification, intended or likely to deceive such importer, manufacturer, dealer, or collector with respect to any fact material to the lawfulness of the sale or other disposition of such firearm or ammunition under the provisions of this chapter;"],[1,"(7) for any person to manufacture or import armor piercing ammunition, unless—"],[2,"(A) the manufacture of such ammunition is for the use of the United States, any department or agency of the United States, any State, or any department, agency, or political subdivision of a State;"],[2,"(B) the manufacture of such ammunition is for the purpose of exportation; or"],[2,"(C) the manufacture or importation of such ammunition is for the purpose of testing or experimentation and has been authorized by the Attorney General;"],[1,"(8) for any manufacturer or importer to sell or deliver armor piercing ammunition, unless such sale or delivery—"],[2,"(A) is for the use of the United States, any department or agency of the United States, any State, or any department, agency, or political subdivision of a State;"],[2,"(B) is for the purpose of exportation; or"],[2,"(C) is for the purpose of testing or experimentation and has been authorized by the Attorney General; 1"],[1,"(9) for any person, other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, who does not reside in any State to receive any firearms unless such receipt is for lawful sporting purposes."],[0,"(b) It shall be unlawful for any licensed importer, licensed manufacturer, licensed dealer, or licensed collector to sell or deliver—"],[1,"(1) any firearm or ammunition to any individual who the licensee knows or has reasonable cause to believe is less than eighteen years of age, and, if the firearm, or ammunition is other than a shotgun or rifle, or ammunition for a shotgun or rifle, to any individual who the licensee knows or has reasonable cause to believe is less than twenty-one years of age;"],[1,"(2) any firearm to any person in any State where the purchase or possession by such person of such firearm would be in violation of any State law or any published ordinance applicable at the place of sale, delivery or other disposition, unless the licensee knows or has reasonable cause to believe that the purchase or possession would not be in violation of such State law or such published ordinance;"],[1,"(3) any firearm to any person who the licensee knows or has reasonable cause to believe does not reside in (or if the person is a corporation or other business entity, does not maintain a place of business in) the State in which the licensee's place of business is located, except that this paragraph (A) shall not apply to the sale or delivery of any rifle or shotgun to a resident of a State other than a State in which the licensee's place of business is located if the transferee meets in person with the transferor to accomplish the transfer, and the sale, delivery, and receipt fully comply with the legal conditions of sale in both such States (and any licensed manufacturer, importer or dealer shall be presumed, for purposes of this subparagraph, in the absence of evidence to the contrary, to have had actual knowledge of the State laws and published ordinances of both States), and (B) shall not apply to the loan or rental of a firearm to any person for temporary use for lawful sporting purposes;"],[1,"(4) to any person any destructive device, machinegun (as defined in section 5845 of the Internal Revenue Code of 1986), short-barreled shotgun, or short-barreled rifle, except as specifically authorized by the Attorney General consistent with public safety and necessity; and"],[1,"(5) any firearm or armor-piercing ammunition to any person unless the licensee notes in his records, required to be kept pursuant to section 923 of this chapter, the name, age, and place of residence of such person if the person is an individual, or the identity and principal and local places of business of such person if the person is a corporation or other business entity."],[0,"Paragraphs (1), (2), (3), and (4) of this subsection shall not apply to transactions between licensed importers, licensed manufacturers, licensed dealers, and licensed collectors. Paragraph (4) of this subsection shall not apply to a sale or delivery to any research organization designated by the Attorney General."],[0,"(c) In any case not otherwise prohibited by this chapter, a licensed importer, licensed manufacturer, or licensed dealer may sell a firearm to a person who does not appear in person at the licensee's business premises (other than another licensed importer, manufacturer, or dealer) only if—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/922?type=usc&year=mostrecent&link-type=html"},"op":7,"head":"§922. Unlawful acts","tname":"Crimes and Criminal Procedure","by":{"0":"passim","1":"19, 19, 19, 19, 19, 19, 19, 19, 19, 19, 19, 19, 19, 19, 19, 19","2":"passim, 6"}},{"t":"usc","label":"18 U.S.C. § 924","url":"https://www.law.cornell.edu/uscode/text/18/924","subs":["(a)(2)","(e)(1)","(2012)","(a)","(a)(1)","(a)(1)(B)","(a)(1)(D)"],"stext":{"head":"§924. Penalties","paras":[[0,"(a)(1) Except as otherwise provided in this subsection, subsection (b), (c), (f), or (p) of this section, or in section 929, whoever—"],[1,"(A) knowingly makes any false statement or representation with respect to the information required by this chapter to be kept in the records of a person licensed under this chapter or in applying for any license or exemption or relief from disability under the provisions of this chapter;"],[1,"(B) knowingly violates subsection (a)(4), (f), (k), or (q) of section 922;"],[1,"(C) knowingly imports or brings into the United States or any possession thereof any firearm or ammunition in violation of section 922(l); or"],[1,"(D) willfully violates any other provision of this chapter,"],[0,"shall be fined under this title, imprisoned not more than five years, or both."],[0,"(2) Whoever knowingly violates subsection (a)(6), (h), (i), (j), or (o) of section 922 shall be fined as provided in this title, imprisoned not more than 10 years, or both."],[0,"(3) Any licensed dealer, licensed importer, licensed manufacturer, or licensed collector who knowingly—"],[1,"(A) makes any false statement or representation with respect to the information required by the provisions of this chapter to be kept in the records of a person licensed under this chapter, or"],[1,"(B) violates subsection (m) of section 922,"],[0,"shall be fined under this title, imprisoned not more than one year, or both."],[0,"(4) Whoever violates section 922(q) shall be fined under this title, imprisoned for not more than 5 years, or both. Notwithstanding any other provision of law, the term of imprisonment imposed under this paragraph shall not run concurrently with any other term of imprisonment imposed under any other provision of law. Except for the authorization of a term of imprisonment of not more than 5 years made in this paragraph, for the purpose of any other law a violation of section 922(q) shall be deemed to be a misdemeanor."],[0,"(5) Whoever knowingly violates subsection (s) or (t) of section 922 shall be fined under this title, imprisoned for not more than 1 year, or both."],[0,"(6)(A)(i) A juvenile who violates section 922(x) shall be fined under this title, imprisoned not more than 1 year, or both, except that a juvenile described in clause (ii) shall be sentenced to probation on appropriate conditions and shall not be incarcerated unless the juvenile fails to comply with a condition of probation."],[0,"(ii) A juvenile is described in this clause if—"],[1,"(I) the offense of which the juvenile is charged is possession of a handgun or ammunition in violation of section 922(x)(2); and"],[1,"(II) the juvenile has not been convicted in any court of an offense (including an offense under section 922(x) or a similar State law, but not including any other offense consisting of conduct that if engaged in by an adult would not constitute an offense) or adjudicated as a juvenile delinquent for conduct that if engaged in by an adult would constitute an offense."],[0,"(B) A person other than a juvenile who knowingly violates section 922(x)—"],[1,"(i) shall be fined under this title, imprisoned not more than 1 year, or both; and"],[1,"(ii) if the person sold, delivered, or otherwise transferred a handgun or ammunition to a juvenile knowing or having reasonable cause to know that the juvenile intended to carry or otherwise possess or discharge or otherwise use the handgun or ammunition in the commission of a crime of violence, shall be fined under this title, imprisoned not more than 10 years, or both."],[0,"(7) Whoever knowingly violates section 931 shall be fined under this title, imprisoned not more than 3 years, or both."],[0,"(8) Whoever knowingly violates subsection (d) or (g) of section 922 shall be fined under this title, imprisoned for not more than 15 years, or both."],[0,"(b) Whoever, with intent to commit therewith an offense punishable by imprisonment for a term exceeding one year, or with knowledge or reasonable cause to believe that an offense punishable by imprisonment for a term exceeding one year is to be committed therewith, ships, transports, or receives a firearm or any ammunition in interstate or foreign commerce shall be fined under this title, or imprisoned not more than ten years, or both."],[0,"(c)(1)(A) Except to the extent that a greater minimum sentence is otherwise provided by this subsection or by any other provision of law, any person who, during and in relation to any crime of violence or drug trafficking crime (including a crime of violence or drug trafficking crime that provides for an enhanced punishment if committed by the use of a deadly or dangerous weapon or device) for which the person may be prosecuted in a court of the United States, uses or carries a firearm, or who, in furtherance of any such crime, possesses a firearm, shall, in addition to the punishment provided for such crime of violence or drug trafficking crime—"],[1,"(i) be sentenced to a term of imprisonment of not less than 5 years;"],[1,"(ii) if the firearm is brandished, be sentenced to a term of imprisonment of not less than 7 years; and"],[1,"(iii) if the firearm is discharged, be sentenced to a term of imprisonment of not less than 10 years."],[0,"(B) If the firearm possessed by a person convicted of a violation of this subsection—"],[1,"(i) is a short-barreled rifle, short-barreled shotgun, or semiautomatic assault weapon, the person shall be sentenced to a term of imprisonment of not less than 10 years; or"],[1,"(ii) is a machinegun or a destructive device, or is equipped with a firearm silencer or firearm muffler, the person shall be sentenced to a term of imprisonment of not less than 30 years."],[0,"(C) In the case of a violation of this subsection that occurs after a prior conviction under this subsection has become final, the person shall—"],[1,"(i) be sentenced to a term of imprisonment of not less than 25 years; and"],[1,"(ii) if the firearm involved is a machinegun or a destructive device, or is equipped with a firearm silencer or firearm muffler, be sentenced to imprisonment for life."],[0,"(D) Notwithstanding any other provision of law—"],[1,"(i) a court shall not place on probation any person convicted of a violation of this subsection; and"],[1,"(ii) no term of imprisonment imposed on a person under this subsection shall run concurrently with any other term of imprisonment imposed on the person, including any term of imprisonment imposed for the crime of violence or drug trafficking crime during which the firearm was used, carried, or possessed."],[0,"(2) For purposes of this subsection, the term \"drug trafficking crime\" means any felony punishable under the Controlled Substances Act (21 U.S.C. 801 et seq.), the Controlled Substances Import and Export Act (21 U.S.C. 951 et seq.), or chapter 705 of title 46."],[0,"(3) For purposes of this subsection the term \"crime of violence\" means an offense that is a felony and—"],[1,"(A) has as an element the use, attempted use, or threatened use of physical force against the person or property of another, or"],[1,"(B) that by its nature, involves a substantial risk that physical force against the person or property of another may be used in the course of committing the offense."],[0,"(4) For purposes of this subsection, the term \"brandish\" means, with respect to a firearm, to display all or part of the firearm, or otherwise make the presence of the firearm known to another person, in order to intimidate that person, regardless of whether the firearm is directly visible to that person."],[0,"(5) Except to the extent that a greater minimum sentence is otherwise provided under this subsection, or by any other provision of law, any person who, during and in relation to any crime of violence or drug trafficking crime (including a crime of violence or drug trafficking crime that provides for an enhanced punishment if committed by the use of a deadly or dangerous weapon or device) for which the person may be prosecuted in a court of the United States, uses or carries armor piercing ammunition, or who, in furtherance of any such crime, possesses armor piercing ammunition, shall, in addition to the punishment provided for such crime of violence or drug trafficking crime or conviction under this section—"],[1,"(A) be sentenced to a term of imprisonment of not less than 15 years; and"],[1,"(B) if death results from the use of such ammunition—"],[2,"(i) if the killing is murder (as defined in section 1111), be punished by death or sentenced to a term of imprisonment for any term of years or for life; and"],[2,"(ii) if the killing is manslaughter (as defined in section 1112), be punished as provided in section 1112."],[0,"(d)(1) Any firearm or ammunition involved in or used in any knowing violation of subsection (a)(4), (a)(6), (f), (g), (h), (i), (j), or (k) of section 922, or knowing importation or bringing into the United States or any possession thereof any firearm or ammunition in violation of section 922(l), or knowing violation of section 924, 932, or 933, or willful violation of any other provision of this chapter or any rule or regulation promulgated thereunder, or any violation of any other criminal law of the United States, or any firearm or ammunition intended to be used in any offense referred to in paragraph (3) of this subsection, where such intent is demonstrated by clear and convincing evidence, shall be subject to seizure and forfeiture, and all provisions of the Internal Revenue Code of 1986 relating to the seizure, forfeiture, and disposition of firearms, as defined in section 5845(a) of that Code, shall, so far as applicable, extend to seizures and forfeitures under the provisions of this chapter: Provided, That upon acquittal of the owner or possessor, or dismissal of the charges against him other than upon motion of the Government prior to trial, or lapse of or court termination of the restraining order to which he is subject, the seized or relinquished firearms or ammunition shall be returned forthwith to the owner or possessor or to a person delegated by the owner or possessor unless the return of the firearms or ammunition would place the owner or possessor or his delegate in violation of law. Any action or proceeding for the forfeiture of firearms or ammunition shall be commenced within one hundred and twenty days of such seizure."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/924?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§924. Penalties","tname":"Crimes and Criminal Procedure","by":{"0":"passim","1":"14, 41, 42, 19, 19, 19, 19, 9, 14, 20, 30","2":"passim"}},{"t":"usc","label":"18 U.S.C. § 1751","url":"https://www.law.cornell.edu/uscode/text/18/1751","subs":["(j)"],"by":{"0":"24"}},{"t":"usc","label":"18 U.S.C. § 2241","url":"https://www.law.cornell.edu/uscode/text/18/2241","subs":["(c)","(d)"],"by":{"0":"13, 13"}},{"t":"usc","label":"18 U.S.C. § 2243","url":"https://www.law.cornell.edu/uscode/text/18/2243","subs":["(a)","(d)"],"stext":{"head":"§2243. Sexual abuse of a minor, a ward, or an individual in Federal custody","paras":[[0,"(a) Of a Minor.—Whoever, in the special maritime and territorial jurisdiction of the United States or in a Federal prison, or in any prison, institution, or facility in which persons are held in custody by direction of or pursuant to a contract or agreement with the head of any Federal department or agency, knowingly engages in a sexual act with another person who—"],[1,"(1) has attained the age of 12 years but has not attained the age of 16 years; and"],[1,"(2) is at least four years younger than the person so engaging;"],[0,"or attempts to do so, shall be fined under this title, imprisoned not more than 15 years, or both."],[0,"(b) Of a Ward.—Whoever, in the special maritime and territorial jurisdiction of the United States or in a Federal prison, or in any prison, institution, or facility in which persons are held in custody by direction of or pursuant to a contract or agreement with the head of any Federal department or agency, knowingly engages in a sexual act with another person who is—"],[1,"(1) in official detention; and"],[1,"(2) under the custodial, supervisory, or disciplinary authority of the person so engaging;"],[0,"or attempts to do so, shall be fined under this title, imprisoned not more than 15 years, or both."],[0,"(c) Of an Individual in Federal Custody.—Whoever, while acting in their capacity as a Federal law enforcement officer, knowingly engages in a sexual act with an individual who is under arrest, under supervision, in detention, or in Federal custody, shall be fined under this title, imprisoned not more than 15 years, or both."],[0,"(d) Defenses.—In a prosecution under subsection (a) of this section, it is a defense, which the defendant must establish by a preponderance of the evidence, that the defendant reasonably believed that the other person had attained the age of 16 years."],[0,"(e) State of Mind Proof Requirement.—In a prosecution under subsection (a) of this section, the Government need not prove that the defendant knew—"],[1,"(1) the age of the other person engaging in the sexual act; or"],[1,"(2) that the requisite age difference existed between the persons so engaging."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/2243?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§2243. Sexual abuse of a minor, a ward, or an individual in Federal custody","tname":"Crimes and Criminal Procedure","by":{"0":"24, 24"}},{"t":"law","label":"Firearm Owners’ Protection Act, Pub. L. No. 99-308","url":"https://www.govinfo.gov/link/statute/100/449","by":{"0":"20, 21","1":"31","2":"4"}},{"t":"law","label":"Pub. L. No. 90-351","url":"https://www.govinfo.gov/link/statute/82/225","by":{"0":"20"}},{"t":"law","label":"Pub. L. No. 90-618","url":"https://www.govinfo.gov/link/statute/82/1223","by":{"0":"20"}},{"t":"case","label":"Abramski v. United States","cite":"573 U.S. 169","y":2014,"id":"2013/12-1493","sc":1,"sum":"The Court held that a firearm purchaser's intent to sell their gun to another buyer is necessary information for the seller's records.","sumSrc":"Oyez","by":{"1":"35, 36, 45"}},{"t":"case","label":"Barrett v. United States","cite":"423 U.S. 212","y":1976,"id":"1975/74-5566","sc":1,"op":1,"sum":"The provision of the Gun Control Act of 1968, 18 U. S. C. § 922 (h), making it unlawful for a convicted felon, inter alia, \"to receive any firearm or ammunition which has been shipped or transported in interstate or foreign commerce,\" held to apply to a convicted felon's intrastate purchase from a retail dealer of a firearm that previously, but independently of the felon's receipt, had been transported in interstate …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"16"}},{"t":"case","label":"Boyce Motor Lines, Inc. v. United States","cite":"342 U.S. 337","y":1952,"id":"scdb/1951-035","sc":1,"op":3,"sum":"The regulation was not void for vagueness, and the District Court should not have dismissed the counts of the indictment based thereon.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"23"}},{"t":"case","label":"Braswell v. United States","cite":"224 F.2d 706","y":1955,"url":"https://www.courtlistener.com/c/F.2d/224/706/","by":{"1":"30"}},{"t":"case","label":"Bryan v. United States","cite":"524 U.S. 184","y":1998,"id":"1997/96-8422","sc":1,"ar":1,"sum":"The Court held that the term \"willfully\" in section 924(a)(1)(D) requires proof only that the defendant knew his conduct was unlawful, not that he also knew of the federal licensing requirement.","sumSrc":"Oyez","by":{"1":"19, 20, 21","2":"5, 11"}},{"t":"case","label":"Cheek v. United States","cite":"498 U.S. 192","y":1991,"id":"1990/89-658","sc":1,"op":1,"sum":"Petitioner Cheek was charged with six counts of willfully failing to file a federal income tax return in violation of § 7203 of the Internal Revenue Code (Code) and three counts of willfully attempting to evade his income taxes in violation of §7201. Although admitting that he had not filed his returns, he testified that he had not acted willfully because he sincerely believed, based on his indoctrination by a group …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"19, 20"}},{"t":"case","label":"Clark v. Martinez","cite":"543 U.S. 371","y":2005,"id":"2004/03-878","sc":1,"sum":"The Court said the requirement that immigrants be detained no longer than reasonably necessary for deportation applied to both admissible and inadmissible immigrants. Because readmission to Cuba was unforeseeable, the detentions of Martinez and Benitez were unreasonable.","sumSrc":"Oyez","by":{"1":"22","2":"21"}},{"t":"case","label":"Dickerson v. New Banner Inst., Inc.","cite":"460 U.S. 103","y":1983,"id":"1982/81-1180","sc":1,"sum":"The firearms disabilities imposed by §§ 922(g)(1) and (h)(1) apply to Kennison and were not removed by the expunction of the record of his guilty plea to the concealed weapon charge.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"16"}},{"t":"case","label":"Dixon v. United States","cite":"548 U.S. 1","y":2006,"id":"2005/05-7053","sc":1,"sum":"In a 7-to-2 decision authored by Justice John Paul Stevens, the Supreme Court held that the government meets its evidentiary burden when it proves beyond a reasonable doubt that the defendant acted \"knowingly\" and \"willfully.\" Dixon had argued that duress would make it impossible for a defendant to act \"willfully\" (and that the government therefore had to prove she did not act under duress in order to prove she acted willfully).","sumSrc":"Oyez","by":{"1":"20"}},{"t":"case","label":"Edmonson v. Leesville Concrete Co.","cite":"500 U.S. 614","y":1991,"id":"1990/89-7743","sc":1,"sum":"A private litigant in a civil case may not use peremptory challenges to exclude jurors on account of race.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"25"}},{"t":"case","label":"Evans v. United States","cite":"504 U.S. 255","y":1992,"id":"1991/90-6105","sc":1,"sum":"An affirmative act of inducement by a public official, such as a demand, is not an element of the offense of extortion \"under color of official right\" prohibited by the Hobbs Act.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"34"}},{"t":"case","label":"Hamling v. United States","cite":"418 U.S. 87","y":1974,"id":"1973/73-507","sc":1,"sum":"Petitioners were convicted of mailing and conspiring to mail an obscene advertising brochure with sexually explicit photographic material relating to their illustrated version (hereafter Illustrated Report) of an official report on obscenity, in violation of 18 U. S. C. §§ 2, 371, and 1461. The indictment under § 1461 charged petitioners in the language of the statute, which provides in pertinent part that obscene …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"23","2":"13"}},{"t":"case","label":"Head v. Hargrave","cite":"105 U.S. 45","y":1881,"id":"scdb/1881-157","sc":1,"sum":"This was an action brought iñ a district court of.Arizona to recover the sum of -$2,0Q0 alleged to be owing by the defendants-to the plaintiffs for professional services as attorneys and counsellors-at-law in that Territory in 1877. and 1878. The complaint alleges that the services wére performed,in several-suits and proceedings, upon a retainer by the^ defendants; and that they were reasonably worth that sum. The …","sumSrc":"Headnote (U.S. Reports)","by":{"1":"37"}},{"t":"case","label":"Huddleston v. United States","cite":"415 U.S. 814","y":1974,"id":"1973/72-1076","sc":1,"sum":"Section 922 (a) (6) applies to the redemption of a firearm from a pawnshop.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"16"}},{"t":"case","label":"Landsdown v. United States","cite":"348 F.2d 405","y":1965,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/348/405/","by":{"1":"30"}},{"t":"case","label":"Lewis v. United States","cite":"445 U.S. 55","y":1980,"id":"1979/78-1595","sc":1,"sum":"Even though petitioner's extant prior state-court felony conviction may be subject to collateral attack under Gideon v. Wainwright, 372 U. S. 335, it could properly be used as a predicate for his subsequent conviction for possession of a firearm in violation of § 1202 (a) (1) of Title VII of the Omnibus Crime Control and Safe Streets Act of 1968.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"16"}},{"t":"case","label":"Loughrin v. United States","cite":"134 S. Ct. 2384","y":2014,"id":"2013/13-316","sc":1,"sum":"The Court held that, to find someone guilty of bank fraud, only one of the two bank fraud statutes must be met, not both.","sumSrc":"Oyez","by":{"1":"17"}},{"t":"case","label":"Muscarello v. United States","cite":"524 U.S. 125","y":1998,"id":"1997/96-1654","sc":1,"op":1,"sum":"The Court held that the phrase \"carries a firearm\" applies to a person who knowingly possesses and conveys firearms in a vehicle, including in the locked glove compartment or trunk of a car, which the person accompanies.","sumSrc":"Oyez","by":{"1":"45"}},{"t":"case","label":"NLRB v. SW Gen., Inc.","cite":"137 S. Ct. 929","y":2017,"id":"2016/15-1251","sc":1,"sum":"The Court determined that the limitations on nominees to vacant positions serving in an acting capacity under the Federal Vacancies Reform Act apply equally to first assistants who take on the position and to those who are selected by the President from within the same agency or from another agency.","sumSrc":"Oyez","by":{"1":"43"}},{"t":"case","label":"Neder v. United States","cite":"527 U.S. 1","y":1999,"id":"1998/97-1985","sc":1,"sum":"The Court held 6-3 that under the harmless-error rule, which applies to a jury instruction that omits an element of an offense, the trial court's error did not render Neder's trial \"fundamentally unfair.\" Thus, the error was harmless.","sumSrc":"Oyez","by":{"1":"46","2":"21"}},{"t":"case","label":"Old Chief v. United States","cite":"519 U.S. 172","y":1997,"id":"1996/95-6556","sc":1,"op":1,"sum":"The Court ruled that a district court abuses its discretion under the Federal Rules of Evidence if it spurns a defendant's offer to concede a prior judgment and admits the full judgment record over the defendant's objection, when the name or nature of the prior offense raises the risk of a verdict tainted by improper considerations, and when the purpose of the evidence is solely to prove the element of prior conviction.","sumSrc":"Oyez","by":{"1":"passim","2":"1, 2, 14, 15"}},{"t":"case","label":"Parker v. Matthews","cite":"567 U.S. 37","y":2012,"id":"2011/11-845","sc":1,"sum":"The Court found that the Sixth Circuit improperly used its own precedent in deciding an appeal from a murder conviction, and that circuit precedent does not constitute clearly established federal law, so it cannot form the basis for habeas relief.","sumSrc":"Oyez","by":{"1":"37"}},{"t":"case","label":"Regalado Cuellar v. United States","cite":"553 U.S. 550","y":2008,"id":"2007/06-1456","sc":1,"sum":"The Court found that prosecutors had failed to prove any of these elements beyond a reasonable doubt.","sumSrc":"Oyez","by":{"1":"36"}},{"t":"case","label":"Robers v. United States","cite":"572 U.S. 639","y":2014,"id":"2013/12-9012","sc":1,"sum":"The Court held that, under the Mandatory Victims Restitution Act, individuals accused of property crime must pay “an amount equal to...the value of the property,” minus “the value...of any part of the property that is returned\" in retribution.","sumSrc":"Oyez","by":{"1":"19"}},{"t":"case","label":"Russello v. United States","cite":"464 U.S. 16","y":1983,"id":"1983/82-472","sc":1,"sum":"The insurance proceeds petitioner received as a result of his arson activities constitute an \"interest\" within the meaning of § 1963(a)(1) and are therefore subject to forfeiture.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"17, 20","2":"6"}},{"t":"case","label":"Small v. United States","cite":"544 U.S. 385","y":2005,"id":"2004/03-750","sc":1,"sum":"The Court held that the federal law's phrase, \"convicted in any court,\" encompassed only domestic, not foreign, convictions. The majority reasoned that in determining the scope of the phrase, it was appropriate to assume Congress had domestic concerns in mind. Moreover, the statute's overall language suggested no intent to reach beyond domestic convictions.","sumSrc":"Oyez","by":{"1":"16"}},{"t":"case","label":"Smith v. United States","cite":"508 U.S. 223","y":1993,"id":"1992/91-8674","sc":1,"sum":"Authored by Justice Sandra Day O'Connor, the Court ruled that a criminal who trades his or her firearm for drugs \"uses\" it \"during and in relation to . . . [a] drug trafficking crime,\" which is within the bounds of the sentence enhancement. Justice O'Connor wrote that Congress intended to make the word \"use\" as broad as possible when it wrote the law.","sumSrc":"Oyez","by":{"1":"45"}},{"t":"case","label":"United States v. Bishop","cite":"412 U.S. 346","y":1973,"id":"1972/71-1698","sc":1,"op":1,"sum":"The word \"willfully\" has the same meaning in §§ 7206 (1) and 7207, connoting the voluntary, intentional violation of a known legal duty, and the distinction between the statutes is found in the additional misconduct that is essential to the violation of the felony provision; hence, the District Court properly refused the requested lesserincluded-offense instruction based on respondent's erroneous con-' tention that …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"20"}},{"t":"case","label":"United States v. Bryant","cite":"523 F.3d 349","y":2008,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/523/349/","op":1,"by":{"1":"33"}},{"t":"case","label":"United States v. Capps","cite":"77 F.3d 350","y":1996,"url":"https://www.courtlistener.com/c/F.3d/77/350/","op":1,"ar":1,"by":{"1":"32"}},{"t":"case","label":"United States v. Castleman","cite":"572 U.S. 157","y":2014,"id":"2013/12-1371","sc":1,"op":1,"sum":"The Court held that a Tennessee man's conviction of domestic violence under state law also prevented him from legally possessing firearms under federal law.","sumSrc":"Oyez","by":{"1":"46"}},{"t":"case","label":"United States v. Chin","cite":"981 F.2d 1275","y":1992,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/981/1275/","by":{"1":"23","2":"10"}},{"t":"case","label":"United States v. Dancy","cite":"861 F.2d 77","y":1988,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/861/77/","op":1,"by":{"1":"32"}},{"t":"case","label":"United States v. Freed","cite":"401 U.S. 601","y":1971,"id":"1970/345","sc":1,"op":1,"sum":"In Haynes v. United States, 390 U. S. 85, the Court held invalid under the Self-Incrimination Clause of the Fifth Amendment provisions of the National Firearms Act, which-constituted parts of an interrelated statutory scheme for taxing certain classes of firearms primarily used for unlawful purposes, and made the potentially incriminating information available to state and other officials. To eliminate the defects …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"44","2":"21"}},{"t":"case","label":"United States v. Goodie","cite":"524 F.2d 515","y":1975,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/524/515/","by":{"1":"30"}},{"t":"case","label":"United States v. Huet","cite":"665 F.3d 588","y":2012,"url":"https://www.courtlistener.com/c/F.3d/665/588/","op":1,"by":{"1":"32"}},{"t":"case","label":"United States v. Jackson","cite":"120 F.3d 1226","y":1997,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/120/1226/","op":1,"by":{"1":"7, 33"}},{"t":"case","label":"United States v. Kind","cite":"194 F.3d 900","y":1999,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/194/900/","op":1,"by":{"1":"32"}},{"t":"case","label":"United States v. Lane","cite":"267 F.3d 715","y":2001,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/267/715/","op":1,"by":{"1":"32"}},{"t":"case","label":"United States v. Miller","cite":"105 F.3d 552","y":1997,"url":"https://www.courtlistener.com/c/F.3d/105/552/","op":1,"by":{"1":"32"}},{"t":"case","label":"United States v. Old Chief","cite":"56 F.3d 75","y":1995,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/56/75/","by":{"1":"26"}},{"t":"case","label":"United States v. Oliver","cite":"683 F.2d 224","y":1982,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/683/224/","op":1,"by":{"1":"30"}},{"t":"case","label":"United States v. Rose","cite":"587 F.3d 695","y":2009,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/587/695/","op":1,"by":{"1":"32"}},{"t":"case","label":"United States v. Smith","cite":"940 F.2d 710","y":1991,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/940/710/","op":1,"by":{"1":"32"}},{"t":"case","label":"United States v. Thomas","cite":"615 F.3d 895","y":2010,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/615/895/","op":1,"by":{"1":"32"}},{"t":"case","label":"United States v. Wiley","cite":"478 F.2d 415","y":1973,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/478/415/","by":{"1":"30"}},{"t":"case","label":"United States v. Williams","cite":"588 F.2d 92","y":1978,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/588/92/","op":1,"by":{"1":"30"}},{"t":"case","label":"United States v. Williams","cite":"553 U.S. 285","y":2008,"id":"2007/06-694","sc":1,"sum":"Held that the statute was not overly broad as written. Justice Scalia noted specifically that offers to engage in illegal transactions are categorically excluded from First Amendment protection, and he characterized the speech of an individual claiming to be in possession of child pornography in this category of unprotected speech.","sumSrc":"Oyez","by":{"1":"36"}},{"t":"case","label":"Utermehle v. Norment","cite":"197 U.S. 40","y":1905,"id":"scdb/1904-143","sc":1,"sum":"Mere ignorance of the law standing, alone does not constitute any defense against its enforcement, and a mistake of law, pure and simple, without the addition of any circumstances of fraud or misrepresentation constitutes no basis for relief at law or in equity and forms no excuse in favor of the party asserting that he made the mistake.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"35"}},{"t":"case","label":"Welch v. United States","cite":"136 S. Ct. 1257","y":2016,"id":"2015/15-6418","sc":1,"sum":"The Court held that the rule the Supreme Court announced in Johnson v. United States regarding what constitutes a violent offense for the purposes of sentencing under the Armed Career Criminal Act applies retroactively.","sumSrc":"Oyez","by":{"1":"42"}},{"t":"law","label":"Pub. L. No. 87-342","url":"https://www.govinfo.gov/link/statute/75/757","by":{"1":"30"}},{"t":"usc","label":"15 U.S.C. § 901","url":"https://www.law.cornell.edu/uscode/text/15/901","by":{"1":"29"}},{"t":"usc","label":"15 U.S.C. § 902","url":"https://www.law.cornell.edu/uscode/text/15/902","subs":["(d)"],"by":{"1":"29"}},{"t":"usc","label":"15 U.S.C. § 905","url":"https://www.law.cornell.edu/uscode/text/15/905","by":{"1":"29"}},{"t":"usc","label":"18 U.S.C. § 921","url":"https://www.law.cornell.edu/uscode/text/18/921","stext":{"head":"§921. Definitions","paras":[[0,"(a) As used in this chapter—"],[0,"(1) The term \"person\" and the term \"whoever\" include any individual, corporation, company, association, firm, partnership, society, or joint stock company."],[0,"(2) The term \"interstate or foreign commerce\" includes commerce between any place in a State and any place outside of that State, or within any possession of the United States (not including the Canal Zone) or the District of Columbia, but such term does not include commerce between places within the same State but through any place outside of that State. The term \"State\" includes the District of Columbia, the Commonwealth of Puerto Rico, and the possessions of the United States (not including the Canal Zone)."],[0,"(3) The term \"firearm\" means (A) any weapon (including a starter gun) which will or is designed to or may readily be converted to expel a projectile by the action of an explosive; (B) the frame or receiver of any such weapon; (C) any firearm muffler or firearm silencer; or (D) any destructive device. Such term does not include an antique firearm."],[0,"(4) The term \"destructive device\" means—"],[1,"(A) any explosive, incendiary, or poison gas—"],[2,"(i) bomb,"],[2,"(ii) grenade,"],[2,"(iii) rocket having a propellant charge of more than four ounces,"],[2,"(iv) missile having an explosive or incendiary charge of more than one-quarter ounce,"],[2,"(v) mine, or"],[2,"(vi) device similar to any of the devices described in the preceding clauses;"],[1,"(B) any type of weapon (other than a shotgun or a shotgun shell which the Attorney General finds is generally recognized as particularly suitable for sporting purposes) by whatever name known which will, or which may be readily converted to, expel a projectile by the action of an explosive or other propellant, and which has any barrel with a bore of more than one-half inch in diameter; and"],[1,"(C) any combination of parts either designed or intended for use in converting any device into any destructive device described in subparagraph (A) or (B) and from which a destructive device may be readily assembled."],[0,"The term \"destructive device\" shall not include any device which is neither designed nor redesigned for use as a weapon; any device, although originally designed for use as a weapon, which is redesigned for use as a signaling, pyrotechnic, line throwing, safety, or similar device; surplus ordnance sold, loaned, or given by the Secretary of the Army pursuant to the provisions of section 7684(2), 7685, or 7686 of title 10; or any other device which the Attorney General finds is not likely to be used as a weapon, is an antique, or is a rifle which the owner intends to use solely for sporting, recreational or cultural purposes."],[0,"(5) The term \"shotgun\" means a weapon designed or redesigned, made or remade, and intended to be fired from the shoulder and designed or redesigned and made or remade to use the energy of an explosive to fire through a smooth bore either a number of ball shot or a single projectile for each single pull of the trigger."],[0,"(6) The term \"short-barreled shotgun\" means a shotgun having one or more barrels less than eighteen inches in length and any weapon made from a shotgun (whether by alteration, modification or otherwise) if such a weapon as modified has an overall length of less than twenty-six inches."],[0,"(7) The term \"rifle\" means a weapon designed or redesigned, made or remade, and intended to be fired from the shoulder and designed or redesigned and made or remade to use the energy of an explosive to fire only a single projectile through a rifled bore for each single pull of the trigger."],[0,"(8) The term \"short-barreled rifle\" means a rifle having one or more barrels less than sixteen inches in length and any weapon made from a rifle (whether by alteration, modification, or otherwise) if such weapon, as modified, has an overall length of less than twenty-six inches."],[0,"(9) The term \"importer\" means any person engaged in the business of importing or bringing firearms or ammunition into the United States for purposes of sale or distribution; and the term \"licensed importer\" means any such person licensed under the provisions of this chapter."],[0,"(10) The term \"manufacturer\" means any person engaged in the business of manufacturing firearms or ammunition for purposes of sale or distribution; and the term \"licensed manufacturer\" means any such person licensed under the provisions of this chapter."],[0,"(11) The term \"dealer\" means (A) any person engaged in the business of selling firearms at wholesale or retail, (B) any person engaged in the business of repairing firearms or of making or fitting special barrels, stocks, or trigger mechanisms to firearms, or (C) any person who is a pawnbroker. The term \"licensed dealer\" means any dealer who is licensed under the provisions of this chapter."],[0,"(12) The term \"pawnbroker\" means any person whose business or occupation includes the taking or receiving, by way of pledge or pawn, of any firearm as security for the payment or repayment of money."],[0,"(13) The term \"collector\" means any person who acquires, holds, or disposes of firearms as curios or relics, as the Attorney General shall by regulation define, and the term \"licensed collector\" means any such person licensed under the provisions of this chapter."],[0,"(14) The term \"indictment\" includes an indictment or information in any court under which a crime punishable by imprisonment for a term exceeding one year may be prosecuted."],[0,"(15) The term \"fugitive from justice\" means any person who has fled from any State to avoid prosecution for a crime or to avoid giving testimony in any criminal proceeding."],[0,"(16) The term \"antique firearm\" means—"],[1,"(A) any firearm (including any firearm with a matchlock, flintlock, percussion cap, or similar type of ignition system) manufactured in or before 1898; or"],[1,"(B) any replica of any firearm described in subparagraph (A) if such replica—"],[2,"(i) is not designed or redesigned for using rimfire or conventional centerfire fixed ammunition, or"],[2,"(ii) uses rimfire or conventional centerfire fixed ammunition which is no longer manufactured in the United States and which is not readily available in the ordinary channels of commercial trade; or"],[1,"(C) any muzzle loading rifle, muzzle loading shotgun, or muzzle loading pistol, which is designed to use black powder, or a black powder substitute, and which cannot use fixed ammunition. For purposes of this subparagraph, the term \"antique firearm\" shall not include any weapon which incorporates a firearm frame or receiver, any firearm which is converted into a muzzle loading weapon, or any muzzle loading weapon which can be readily converted to fire fixed ammunition by replacing the barrel, bolt, breechblock, or any combination thereof."],[0,"(17)(A) The term \"ammunition\" means ammunition or cartridge cases, primers, bullets, or propellent powder designed for use in any firearm."],[0,"(B) The term \"armor piercing ammunition\" means—"],[1,"(i) a projectile or projectile core which may be used in a handgun and which is constructed entirely (excluding the presence of traces of other substances) from one or a combination of tungsten alloys, steel, iron, brass, bronze, beryllium copper, or depleted uranium; or"],[1,"(ii) a full jacketed projectile larger than .22 caliber designed and intended for use in a handgun and whose jacket has a weight of more than 25 percent of the total weight of the projectile."],[0,"(C) The term \"armor piercing ammunition\" does not include shotgun shot required by Federal or State environmental or game regulations for hunting purposes, a frangible projectile designed for target shooting, a projectile which the Attorney General finds is primarily intended to be used for sporting purposes, or any other projectile or projectile core which the Attorney General finds is intended to be used for industrial purposes, including a charge used in an oil and gas well perforating device."],[0,"(18) The term \"Attorney General\" means the Attorney General of the United States 1"],[0,"(19) The term \"published ordinance\" means a published law of any political subdivision of a State which the Attorney General determines to be relevant to the enforcement of this chapter and which is contained on a list compiled by the Attorney General, which list shall be published in the Federal Register, revised annually, and furnished to each licensee under this chapter."],[0,"(20) The term \"crime punishable by imprisonment for a term exceeding one year\" does not include—"],[1,"(A) any Federal or State offenses pertaining to antitrust violations, unfair trade practices, restraints of trade, or other similar offenses relating to the regulation of business practices, or"],[1,"(B) any State offense classified by the laws of the State as a misdemeanor and punishable by a term of imprisonment of two years or less."],[0,"What constitutes a conviction of such a crime shall be determined in accordance with the law of the jurisdiction in which the proceedings were held. Any conviction which has been expunged, or set aside or for which a person has been pardoned or has had civil rights restored shall not be considered a conviction for purposes of this chapter, unless such pardon, expungement, or restoration of civil rights expressly provides that the person may not ship, transport, possess, or receive firearms."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/921?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§921. Definitions","tname":"Crimes and Criminal Procedure","by":{"1":"30"}},{"t":"law","label":"and rules—Continued:, Pub. L. No. 99-408","url":"https://www.govinfo.gov/link/statute/100/920","by":{"1":"33"}},{"t":"law","label":"Pub. L. No. 99-570","url":"https://www.govinfo.gov/link/statute/100/3207","by":{"1":"33"}},{"t":"law","label":"Pub. L. No. 100-649","url":"https://www.govinfo.gov/link/statute/102/3816","by":{"1":"33"}},{"t":"law","label":"Pub. L. No. 100-690","url":"https://www.govinfo.gov/link/statute/102/4181","by":{"1":"19"}},{"t":"law","label":"Pub. L. No. 101-647","url":"https://www.govinfo.gov/link/statute/104/4829","by":{"1":"33"}},{"t":"law","label":"Pub. L. No. 103-159","url":"https://www.govinfo.gov/link/statute/107/1536","by":{"1":"33"}},{"t":"law","label":"Pub. L. No. 103-322","url":"https://www.govinfo.gov/link/statute/108/1973","by":{"1":"33"}},{"t":"law","label":"Pub. L. No. 104-208","url":"https://www.govinfo.gov/link/plaw/104/public/208","by":{"1":"33"}},{"t":"law","label":"Pub. L. No. 104-294","url":"https://www.govinfo.gov/link/plaw/104/public/294","by":{"1":"33"}},{"t":"law","label":"Pub. L. No. 105-277","url":"https://www.govinfo.gov/link/plaw/105/public/277","by":{"1":"33"}},{"t":"law","label":"Pub. L. No. 105-386","url":"https://www.govinfo.gov/link/plaw/105/public/386","by":{"1":"33"}},{"t":"law","label":"Pub. L. No. 107-273","url":"https://www.govinfo.gov/link/plaw/107/public/273","by":{"1":"33"}},{"t":"law","label":"Pub. L. No. 107-296","url":"https://www.govinfo.gov/link/plaw/107/public/296","by":{"1":"33"}},{"t":"law","label":"and rules—Continued:, Pub. L. No. 109-92","url":"https://www.govinfo.gov/link/plaw/109/public/92","by":{"1":"33"}},{"t":"law","label":"Pub. L. No. 109-304","url":"https://www.govinfo.gov/link/plaw/109/public/304","by":{"1":"33"}},{"t":"law","label":"Pub. L. No. 114-94","url":"https://www.govinfo.gov/link/plaw/114/public/94","by":{"1":"33"}},{"t":"law","label":"Pub. L. No. 115-391","url":"https://www.govinfo.gov/link/plaw/115/public/391","by":{"1":"33"}},{"t":"usc","label":"8 U.S.C. § 1182","url":"https://www.law.cornell.edu/uscode/text/8/1182","subs":["(a)(6)(C)(ii)"],"by":{"1":"25"}},{"t":"usc","label":"8 U.S.C. § 1184","url":"https://www.law.cornell.edu/uscode/text/8/1184","subs":["(a)(1)"],"by":{"1":"24"}},{"t":"usc","label":"8 U.S.C. § 1185","url":"https://www.law.cornell.edu/uscode/text/8/1185","subs":["(a)(1)"],"by":{"1":"24"}},{"t":"usc","label":"8 U.S.C. § 1225","url":"https://www.law.cornell.edu/uscode/text/8/1225","subs":["(b)(2)(A)"],"by":{"1":"24"}},{"t":"usc","label":"8 U.S.C. § 1227","url":"https://www.law.cornell.edu/uscode/text/8/1227","subs":["(a)(1)(C)(i)","(a)(3)(D)"],"by":{"1":"24, 25"}},{"t":"usc","label":"8 U.S.C. § 1325","url":"https://www.law.cornell.edu/uscode/text/8/1325","subs":["(a)","(b)"],"by":{"1":"24, 24"}},{"t":"usc","label":"8 U.S.C. § 1361","url":"https://www.law.cornell.edu/uscode/text/8/1361","by":{"1":"24"}},{"t":"usc","label":"8 U.S.C. § 1611","url":"https://www.law.cornell.edu/uscode/text/8/1611","by":{"1":"25"}},{"t":"usc","label":"8 U.S.C. § 1621","url":"https://www.law.cornell.edu/uscode/text/8/1621","subs":["(a)","(c)(1)"],"by":{"1":"25, 25"}},{"t":"usc","label":"8 U.S.C. § 1641","url":"https://www.law.cornell.edu/uscode/text/8/1641","subs":["(b)"],"by":{"1":"25"}},{"t":"usc","label":"18 U.S.C. § 201","url":"https://www.law.cornell.edu/uscode/text/18/201","subs":["(b)(2)"],"by":{"1":"23"}},{"t":"usc","label":"18 U.S.C. § 611","url":"https://www.law.cornell.edu/uscode/text/18/611","subs":["(a)","(b)","(c)"],"by":{"1":"25, 25, 25"}},{"t":"usc","label":"18 U.S.C. § 1015","url":"https://www.law.cornell.edu/uscode/text/18/1015","by":{"1":"25"}},{"t":"usc","label":"18 U.S.C. § 1924","url":"https://www.law.cornell.edu/uscode/text/18/1924","subs":["(a)"],"stext":{"head":"§1924. Unauthorized removal and retention of classified documents or material","paras":[[0,"(a) Whoever, being an officer, employee, contractor, or consultant of the United States, and, by virtue of his office, employment, position, or contract, becomes possessed of documents or materials containing classified information of the United States, knowingly removes such documents or materials without authority and with the intent to retain such documents or materials at an unauthorized location shall be fined under this title or imprisoned for not more than five years, or both."],[0,"(b) For purposes of this section, the provision of documents and materials to the Congress shall not constitute an offense under subsection (a)."],[0,"(c) In this section, the term \"classified information of the United States\" means information originated, owned, or possessed by the United States Government concerning the national defense or foreign relations of the United States that has been determined pursuant to law or Executive order to require protection against unauthorized disclosure in the interests of national security."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1924?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§1924. Unauthorized removal and retention of classified documents or material","tname":"Crimes and Criminal Procedure","by":{"1":"23"}},{"t":"usc","label":"18 U.S.C. § 2251","url":"https://www.law.cornell.edu/uscode/text/18/2251","subs":["(b)"],"stext":{"head":"§2251. Sexual exploitation of children","paras":[[0,"(a) Any person who employs, uses, persuades, induces, entices, or coerces any minor to engage in, or who has a minor assist any other person to engage in, or who transports any minor in or affecting interstate or foreign commerce, or in any Territory or Possession of the United States, with the intent that such minor engage in, any sexually explicit conduct for the purpose of producing any visual depiction of such conduct or for the purpose of transmitting a live visual depiction of such conduct, shall be punished as provided under subsection (e), if such person knows or has reason to know that such visual depiction will be transported or transmitted using any means or facility of interstate or foreign commerce or in or affecting interstate or foreign commerce or mailed, if that visual depiction was produced or transmitted using materials that have been mailed, shipped, or transported in or affecting interstate or foreign commerce by any means, including by computer, or if such visual depiction has actually been transported or transmitted using any means or facility of interstate or foreign commerce or in or affecting interstate or foreign commerce or mailed."],[0,"(b) Any parent, legal guardian, or person having custody or control of a minor who knowingly permits such minor to engage in, or to assist any other person to engage in, sexually explicit conduct for the purpose of producing any visual depiction of such conduct or for the purpose of transmitting a live visual depiction of such conduct shall be punished as provided under subsection (e) of this section, if such parent, legal guardian, or person knows or has reason to know that such visual depiction will be transported or transmitted using any means or facility of interstate or foreign commerce or in or affecting interstate or foreign commerce or mailed, if that visual depiction was produced or transmitted using materials that have been mailed, shipped, or transported in or affecting interstate or foreign commerce by any means, including by computer, or if such visual depiction has actually been transported or transmitted using any means or facility of interstate or foreign commerce or in or affecting interstate or foreign commerce or mailed."],[0,"(c)(1) Any person who, in a circumstance described in paragraph (2), employs, uses, persuades, induces, entices, or coerces any minor to engage in, or who has a minor assist any other person to engage in, any sexually explicit conduct outside of the United States, its territories or possessions, for the purpose of producing any visual depiction of such conduct, shall be punished as provided under subsection (e)."],[0,"(2) The circumstance referred to in paragraph (1) is that—"],[1,"(A) the person intends such visual depiction to be transported to the United States, its territories or possessions, by any means, including by using any means or facility of interstate or foreign commerce or mail; or"],[1,"(B) the person transports such visual depiction to the United States, its territories or possessions, by any means, including by using any means or facility of interstate or foreign commerce or mail."],[0,"(d)(1) Any person who, in a circumstance described in paragraph (2), knowingly makes, prints, or publishes, or causes to be made, printed, or published, any notice or advertisement seeking or offering—"],[1,"(A) to receive, exchange, buy, produce, display, distribute, or reproduce, any visual depiction, if the production of such visual depiction involves the use of a minor engaging in sexually explicit conduct and such visual depiction is of such conduct; or"],[1,"(B) participation in any act of sexually explicit conduct by or with any minor for the purpose of producing a visual depiction of such conduct;"],[0,"shall be punished as provided under subsection (e)."],[0,"(2) The circumstance referred to in paragraph (1) is that—"],[1,"(A) such person knows or has reason to know that such notice or advertisement will be transported using any means or facility of interstate or foreign commerce or in or affecting interstate or foreign commerce by any means including by computer or mailed; or"],[1,"(B) such notice or advertisement is transported using any means or facility of interstate or foreign commerce or in or affecting interstate or foreign commerce by any means including by computer or mailed."],[0,"(e) Any individual who violates, or attempts or conspires to violate, this section shall be fined under this title and imprisoned not less than 15 years nor more than 30 years, but if such person has one prior conviction under this chapter, section 1591, chapter 71, chapter 109A, or chapter 117, or under the Uniform Code of Military Justice or the laws of any State relating to aggravated sexual abuse, sexual abuse, abusive sexual contact involving a minor or ward, or sex trafficking of children, or the production, possession, receipt, mailing, sale, distribution, shipment, or transportation of child pornography, such person shall be fined under this title and imprisoned for not less than 25 years nor more than 50 years, but if such person has 2 or more prior convictions under this chapter, chapter 71, chapter 109A, or chapter 117, or under the Uniform Code of Military Justice or the laws of any State relating to the sexual exploitation of children, such person shall be fined under this title and imprisoned not less than 35 years nor more than life. Any organization that violates, or attempts or conspires to violate, this section shall be fined under this title. Whoever, in the course of an offense under this section, engages in conduct that results in the death of a person, shall be punished by death or imprisoned for not less than 30 years or for life."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/2251?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§2251. Sexual exploitation of children","tname":"Crimes and Criminal Procedure","by":{"1":"24"}},{"t":"usc","label":"21 U.S.C. § 861","url":"https://www.law.cornell.edu/uscode/text/21/861","subs":["(a)(2)","(b)","(c)"],"stext":{"head":"§861. Employment or use of persons under 18 years of age in drug operations","paras":[[0,"(a) Unlawful acts"],[0,"It shall be unlawful for any person at least eighteen years of age to knowingly and intentionally—"],[1,"(1) employ, hire, use, persuade, induce, entice, or coerce, a person under eighteen years of age to violate any provision of this subchapter or subchapter II;"],[1,"(2) employ, hire, use, persuade, induce, entice, or coerce, a person under eighteen years of age to assist in avoiding detection or apprehension for any offense of this subchapter or subchapter II by any Federal, State, or local law enforcement official; or"],[1,"(3) receive a controlled substance from a person under 18 years of age, other than an immediate family member, in violation of this subchapter or subchapter II."],[0,"(b) Penalty for first offense"],[0,"Any person who violates subsection (a) is subject to twice the maximum punishment otherwise authorized and at least twice any term of supervised release otherwise authorized for a first offense. Except to the extent a greater minimum sentence is otherwise provided, a term of imprisonment under this subsection shall not be less than one year."],[0,"(c) Penalty for subsequent offenses"],[0,"Any person who violates subsection (a) after a prior conviction under subsection (a) of this section has become final, is subject to three times the maximum punishment otherwise authorized and at least three times any term of supervised release otherwise authorized for a first offense. Except to the extent a greater minimum sentence is otherwise provided, a term of imprisonment under this subsection shall not be less than one year. Penalties for third and subsequent convictions shall be governed by section 841(b)(1)(A) of this title."],[0,"(d) Penalty for providing or distributing controlled substance to underage person"],[0,"Any person who violates subsection (a)(1) or (2) 1"],[1,"(1) by knowingly providing or distributing a controlled substance or a controlled substance analogue to any person under eighteen years of age; or"],[1,"(2) if the person employed, hired, or used is fourteen years of age or younger,"],[0,"shall be subject to a term of imprisonment for not more than five years or a fine of not more than $50,000, or both, in addition to any other punishment authorized by this section."],[0,"(e) Suspension of sentence; probation; parole"],[0,"In any case of any sentence imposed under this section, imposition or execution of such sentence shall not be suspended and probation shall not be granted. An individual convicted under this section of an offense for which a mandatory minimum term of imprisonment is applicable shall not be eligible for parole under section 4202 of title 18 2 until the individual has served the mandatory term of imprisonment as enhanced by this section."],[0,"(f) Distribution of controlled substance to pregnant individual"],[0,"Except as authorized by this subchapter, it shall be unlawful for any person to knowingly or intentionally provide or distribute any controlled substance to a pregnant individual in violation of any provision of this subchapter. Any person who violates this subsection shall be subject to the provisions of subsections (b), (c), and (e)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/861?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§861. Employment or use of persons under 18 years of age in drug operations","tname":"Food and Drugs","by":{"1":"23, 23, 23"}},{"t":"usc","label":"26 U.S.C. § 5845","url":"https://www.law.cornell.edu/uscode/text/26/5845","subs":["(a)(6)","(b)"],"by":{"1":"44, 44"}},{"t":"usc","label":"26 U.S.C. § 5861","url":"https://www.law.cornell.edu/uscode/text/26/5861","subs":["(d)"],"by":{"1":"44"}},{"t":"usc","label":"28 U.S.C. § 1864","url":"https://www.law.cornell.edu/uscode/text/28/1864","subs":["(a)"],"by":{"1":"24"}},{"t":"usc","label":"28 U.S.C. § 1865","url":"https://www.law.cornell.edu/uscode/text/28/1865","subs":["(a)","(b)(1)","(b)(5)"],"by":{"1":"24, 24, 24"}},{"t":"rule","label":"Fed. R. Crim. P. 11","url":"https://www.law.cornell.edu/rules/frcrmp/rule_11","subs":["(b)(1)(H)"],"by":{"1":"37"}},{"t":"case","label":"Alexander v. Sandoval","cite":"532 U.S. 275","y":2001,"id":"2000/99-1908","sc":1,"sum":"The Court held that there is no private right of action to enforce disparate-impact regulations promulgated under Title VI. \"Title VI itself directly reaches only instances of intentional discrimination,\" wrote Justice Scalia, \"[n]either as originally enacted nor as later amended does Title VI display an intent to create a freestanding private right of action to enforce regulations promulgated under [section 602].\" Justice John Paul Stevens filed a dissenting opinion, which was join by Justices David H. Souter, Ruth Bader Ginsburg, and Stephen G. Breyer.","sumSrc":"Oyez","by":{"2":"20"}},{"t":"case","label":"Arthur Andersen LLP v. United States","cite":"544 U.S. 696","y":2005,"id":"2004/04-368","sc":1,"sum":"The Court held that the jury instructions failed to convey that the federal document law required a \"consciousness of wrongdoing\" for conviction. There was nothing inherently corrupt in ordering employees to destroy documents, even if the aim was to keep the documents from the government.","sumSrc":"Oyez","by":{"2":"7, 8, 9"}},{"t":"case","label":"Ball v. United States","cite":"470 U.S. 856","y":1985,"id":"1984/84-5004","sc":1,"sum":"Congress did not intend a convicted felon, in petitioner's position, to be punished under both § 922(h) and § 1202(a)(1). Congress recognized that a felon who receives a firearm inevitably also possesses it, and therefore did not intend to subject that person to two convictions for the same criminal act; the legislative history supports this reading of congressional intent. While the Government may seek a …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"4"}},{"t":"case","label":"Descamps v. United States","cite":"570 U.S. 254","y":2013,"id":"2012/11-9540","sc":1,"sum":"The Court held that it was improper to apply the categorical approach in which the courts apply elements of a prior conviction with elements of a generic crime in order to enhance a sentence under the ACCA.","sumSrc":"Oyez","by":{"2":"18"}},{"t":"case","label":"Hinck v. United States","cite":"550 U.S. 501","y":2007,"id":"2006/06-376","sc":1,"sum":"The Court reasoned that its ruling was consistent with the principle that when Congress enacts a detailed, specific judicial remedy (such as 6404(e)(1)) where there was no remedy before, the new remedy will be regarded as exclusive.","sumSrc":"Oyez","by":{"2":"6"}},{"t":"case","label":"Jones v. Liberty Glass Co.","cite":"332 U.S. 524","y":1947,"id":"scdb/1947-015","sc":1,"sum":"1. Under § 322 (b) (1) of the Internal Revenue Code, a claim for refund of federal income tax, whether arising out of an income tax \"erroneously or illegally assessed or collected\" or not, must be. filed within three years from the time the return was filed or within two years from the time the tax was paid. The four-year period prescribed by § 3313 is inapplicable to such a claim. Pp. 525-526, 534-535.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"20"}},{"t":"case","label":"McFadden v. United States","cite":"135 S. Ct. 2298","y":2015,"id":"2014/14-378","sc":1,"sum":"The Court decided that in order to fulfill the intent element of The Controlled Substance Analogue Enforcement Act of 1986, a person must either know that the substance is a controlled substance or be aware of what the substance is without knowing that it is controlled.","sumSrc":"Oyez","by":{"2":"1, 12, 19"}},{"t":"case","label":"Microsoft Corp. v. I4I Ltd. P’ship","cite":"564 U.S. 91","y":2011,"id":"2010/10-290","sc":1,"sum":"The Court held that a challenge to a patent's validity must offer clear and convincing evidence.","sumSrc":"Oyez","by":{"2":"6, 7"}},{"t":"case","label":"RadLAX Gateway Hotel, LLC v. Amalgamated Bank","cite":"566 U.S. 639","y":2012,"id":"2011/11-166","sc":1,"sum":"The Court held that a company could not obtain confirmation of a Chapter 11 bankruptcy plan that provided for the sale of its assets free from lien without permitting a bank to credit-bid at the sale.","sumSrc":"Oyez","by":{"2":"6"}},{"t":"case","label":"United States v. Bridgeforth","cite":"441 F.3d 864","y":2006,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/441/864/","by":{"2":"17"}},{"t":"case","label":"United States v. Crooked Arm","cite":"853 F.3d 1065","y":2017,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/853/1065/","by":{"2":"17"}},{"t":"case","label":"United States v. Wells","cite":"519 U.S. 482","y":1997,"id":"1996/95-1228","sc":1,"sum":"Authored by Justice David H. Souter, the Court ruled that the materiality of falsehood is not an element of the crime of knowingly making a false statement to a federally insured bank. Justice Souter wrote for the court that prosecutors need not prove that a lie was relevant enough to affect the outcome of a bank's decision because the law does not require such materiality.","sumSrc":"Oyez","by":{"2":"4"}},{"t":"case","label":"United States v. Wilson","cite":"503 U.S. 333","y":1992,"id":"1991/90-1745","sc":1,"sum":"It is the Attorney General who computes the amount of the § 3585(b) credit after the defendant has begun to serve his sentence.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"18"}},{"t":"case","label":"United States v. Yermian","cite":"468 U.S. 63","y":1984,"id":"1983/83-346","sc":1,"op":1,"sum":"The Court held that the language of the statute applied the requirement of knowledge to the act of making false statements, rather than the jurisdiction. The Court also held that there was no legislative history to support the reading that Congress intended intent to deceive the federal government to be an element of the crime.","sumSrc":"Oyez","by":{"2":"3, 4"}},{"t":"usc","label":"18 U.S.C. § 1001","url":"https://www.law.cornell.edu/uscode/text/18/1001","by":{"2":"10"}},{"t":"usc","label":"18 U.S.C. § 1512","url":"https://www.law.cornell.edu/uscode/text/18/1512","subs":["(b)(2)"],"by":{"2":"8"}},{"t":"rule","label":"Fed. R. Evid. 403","url":"https://www.law.cornell.edu/rules/fre/rule_403","by":{"2":"14"}}]};